* NQUE -- N-Queens solver (PL/I), board display: board left, info panel right.
* BRD1..BRD23 are the 2n+1 board rows (n <= 11). MARK=Q:YELLOW paints every
* Q in yellow on the blue grid; the field content stays plain text.
MAP NQUE2 SIZE 24x80
  FIELD BRD1   AT 0,0  LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD2   AT 1,0  LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD3   AT 2,0  LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD4   AT 3,0  LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD5   AT 4,0  LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD6   AT 5,0  LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD7   AT 6,0  LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD8   AT 7,0  LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD9   AT 8,0  LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD10  AT 9,0  LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD11  AT 10,0 LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD12  AT 11,0 LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD13  AT 12,0 LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD14  AT 13,0 LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD15  AT 14,0 LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD16  AT 15,0 LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD17  AT 16,0 LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD18  AT 17,0 LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD19  AT 18,0 LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD20  AT 19,0 LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD21  AT 20,0 LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD22  AT 21,0 LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD BRD23  AT 22,0 LEN 23 PROT BRIGHT COLOR=BLUE MARK=Q:YELLOW
  FIELD AT 0,25  LEN 53 PROT BRIGHT COLOR=WHITE "BRICKS N-QUEENS SOLVER   NQUE"
  FIELD AT 2,25  LEN 17 PROT COLOR=TURQUOISE    "Board size n    :"
  FIELD NOUT     AT 2,43 LEN 35 PROT BRIGHT COLOR=WHITE
  FIELD AT 3,25  LEN 17 PROT COLOR=TURQUOISE    "Mirror filter   :"
  FIELD MOUT     AT 3,43 LEN 35 PROT BRIGHT COLOR=WHITE
  FIELD AT 4,25  LEN 17 PROT COLOR=TURQUOISE    "All solutions   :"
  FIELD ALLOUT   AT 4,43 LEN 35 PROT BRIGHT COLOR=WHITE
  FIELD AT 5,25  LEN 17 PROT COLOR=TURQUOISE    "Unique (8 sym)  :"
  FIELD UNQOUT   AT 5,43 LEN 35 PROT BRIGHT COLOR=WHITE
  FIELD AT 6,25  LEN 17 PROT COLOR=TURQUOISE    "Boards kept     :"
  FIELD KEPTOUT  AT 6,43 LEN 35 PROT BRIGHT COLOR=WHITE
  FIELD AT 7,25  LEN 17 PROT COLOR=TURQUOISE    "Search time     :"
  FIELD ELAPOUT  AT 7,43 LEN 35 PROT BRIGHT COLOR=WHITE
  FIELD BRDOUT   AT 9,25  LEN 53 PROT BRIGHT COLOR=YELLOW
  FIELD SOLOUT   AT 10,25 LEN 53 PROT COLOR=GREEN
  FIELD COLSOUT  AT 11,25 LEN 53 PROT COLOR=GREEN
  FIELD MSG      AT 13,25 LEN 53 PROT COLOR=TURQUOISE
  FIELD AT 20,25 LEN 53 PROT COLOR=BLUE         "ENTER/PF8=Next board   PF7=Previous board"
  FIELD AT 21,25 LEN 53 PROT COLOR=BLUE         "PF3=New search         PF12=End"
  FIELD AT 22,25 LEN 53 PROT DIM                "Q = queen (yellow)   + - ! = grid (blue)"
  CURSOR         AT 23,1
ENDMAP
